import{_ as i,l as n,o as e,c as l,v as t,p as s,x as o,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"商过滤器","description":"","frontmatter":{"title":"商过滤器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/quotient-filter.md","filePath":"cs/quotient-filter.md","lastUpdated":1789023840000}'),p={name:"cs/quotient-filter.md"};function u(B,a,_,E,m,f){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="商过滤器" tabindex="-1">商过滤器 <a class="header-anchor" href="#商过滤器" aria-label="Permalink to &quot;商过滤器&quot;">​</a></h1><div class="epigraph"><p>哈希拆成商与余；槽按商顺序紧排，用几比特元数据标簇的起止，查找沿簇线性探测。</p><footer>—— 据 Bender, Farach-Colton, Johnson, Kuszmaul, Medjedovic, Montes, Shetty, Spillane and Zadok, Don&#39;t Thrash: How to Cache Your Hash on Flash, PVLDB 2012 整理</footer></div><p><a href="/cs/cuckoo-filter">上一课</a> 两桶随机跳。<a href="/cs/locality-principle">局部性</a> 上线性探测更吃缓存与 SSD。<a href="/cs/robin-cuckoo">Robin Hood</a> 已在精确表里用过距离。本课不踢两巢。缺口是 quotient filter：把键的哈希写成 \\(q\\) 位商 + \\(r\\) 位余，表按下标 \\(q\\) 的主桶存放余数串。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Bloom/布谷随机访存多。商过滤器：理想位置是槽 \\(q\\)，冲突把余数向后挪但仍属同一 runs/cluster，用 <code>is_occupied</code> / <code>is_continuation</code> / <code>is_shifted</code> 三比特描述。查找：从 \\(q\\) 找到本簇，扫余数是否匹配。缺口是<strong>用商当地址、余当指纹</strong>，顺序扫描短簇，外存友好。</p><p><span class="marginnote">Bender et al., <em>PVLDB</em>, 2012（Don&#39;t Thrash… on Flash）。可删：在 run 里摘余数并修元数据。假阳性约 \\(2^{-r}\\) 量级。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>插入：定位 run，插入余数保持有序或按移位规则，更新三比特。满则再哈希扩容。合并两个过滤器：同参数时可归并有序 runs，适合 LSM 思想——后课 LSM 再接。</p>',8)),(e(),s(h,null,{default:o(()=>[c(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%93%88%E5%B8%8C%22%5D%20--%3E%20Q%5B%22%E5%95%86%3A%20%E4%B8%BB%E6%A7%BD%22%5D%0A%20%20H%20--%3E%20R%5B%22%E4%BD%99%3A%20%E6%8C%87%E7%BA%B9%22%5D%0A%20%20Q%20--%3E%20RUN%5B%22%E7%B0%87%E5%86%85%E8%BF%9E%E7%BB%AD%E4%BD%99%E6%95%B0%22%5D%0A%20%20META%5B%22%E5%8D%A0%E7%94%A8%2F%E8%BF%9E%E7%BB%AD%2F%E7%A7%BB%E4%BD%8D%E6%AF%94%E7%89%B9%22%5D%20--%3E%20RUN%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与开放寻址精确表：这里不存键，只存余数，故近似。与布谷：访存更顺序，插入移位可能 \\(\\Theta(\\text{簇长})\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>三比特不变式保证能从任意 occupied 槽重建 run 边界。实现易错，教学以不变式为主。Flash：少随机写，符合论文动机。不要用商过滤器当精确完美散列。</p><p>下一课从成员转到相似：MinHash 估计 Jaccard。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 counting quotient filter 全文写完。并发 QF 有后续工作，点名即可。集合相似度不是过滤器合同。</p><p>后课默认：外存友好近似集可用商过滤器。Jaccard 近似用 MinHash 与 LSH。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>商过滤器：商定位、余数紧排、三比特描簇。</li><li>可删、顺序访存好；假阳性随余数位。</li><li>下一课估集合相似而非成员。</li><li>出处：Bender et al., <em>PVLDB</em>, 2012。</li></ul>',9))])}const A=i(p,[["render",u]]);export{q as __pageData,A as default};
